import{Lt as e,Vt as t,Z as n,_t as r,bt as i,mt as a,vt as o,yt as s}from"./chunks/framework.CsLlEPF4.js";import"./chunks/assets.Cofv-KFd.js";var c=JSON.parse(`{"title":"文档修改指南","description":"","frontmatter":{"title":"文档修改指南","icon":"flag","date":"2023-07-20T23:05:53.000Z"},"headers":[],"relativePath":"contributing/wiki.md","filePath":"wiki/contributing/wiki.md"}`),l={name:`contributing/wiki.md`},u={id:`方法-2-通过代码空间在线修改`,tabindex:`-1`};function d(n,c,l,d,f,p){let m=t(`Badge`),h=t(`NolebaseGitContributors`),g=t(`NolebaseGitChangelog`);return e(),r(`div`,null,[c[3]||=o(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /contributingwiki.md for this page in Markdown format</div><h1 id="文档修改指南" tabindex="-1">文档修改指南 <a class="header-anchor" href="#文档修改指南" aria-label="Permalink to “文档修改指南”">​</a></h1><h2 id="项目概述" tabindex="-1">项目概述 <a class="header-anchor" href="#项目概述" aria-label="Permalink to “项目概述”">​</a></h2><p>本文档使用 Markdown 语法编写，Markdown 文件存储在 GitHub 上，使用 VitePress 作为静态页面生成器，通过 GitHub Actions 自动构建网站，并托管在 Netlify 上。</p><p>当然，您实际上不需要知道上面的名词代表的是什么，您只需要根据后续小节提供的 <a href="#修改方法">修改方法</a>，并参阅 <a href="./markdown">文档风格和语法指南</a> ，就可以完成文档的贡献。</p><p>目前仓库地址为 <a href="https://github.com/zotero-chinese/wiki/" target="_blank" rel="noreferrer">https://github.com/zotero-chinese/wiki/</a> 。</p><div class="info custom-block"><p class="custom-block-title">需要 GitHub 账号</p><p>文档源码开源托管在 <a href="https://github.com/" target="_blank" rel="noreferrer">GitHub</a> 上，因此读者需要一个 GitHub 账户才能提交 PR。</p></div><h2 id="文档维护范围" tabindex="-1">文档维护范围 <a class="header-anchor" href="#文档维护范围" aria-label="Permalink to “文档维护范围”">​</a></h2><p>文档的维护与更新主要包括几个方面：</p><ul><li>修正错别字、语句不通等</li><li>修正文档中的错误或不清晰的描述</li><li>文档里出现「TODO」、「施工中」、「待办」等字样的内容</li><li>我们在文档仓库里列出的 <a href="https://github.com/zotero-chinese/wiki/issues" target="_blank" rel="noreferrer">待办项</a></li><li>调整章节结构，使文档条理更清晰</li><li>增加示例、专题或入门教程</li><li>其他任何你认为有必要修改的地方</li></ul><p>如果您期望调整章节结构或对文档进行较大规模的修改重构，希望您可以先在文档仓库的 ISSUE 里发布一个帖子，与我们讨论后再进行。</p><h2 id="修改方法" tabindex="-1">修改方法 <a class="header-anchor" href="#修改方法" aria-label="Permalink to “修改方法”">​</a></h2><div class="tip custom-block"><p class="custom-block-title">请根据实际需要选择修改方法</p><p>为了降低上手门槛，我们根据需要修改的量和难易程度提供了以下几种修改方法。</p></div><h3 id="方法-1-在-github-上在线修改" tabindex="-1">方法 1：在 GitHub 上在线修改 <a class="header-anchor" href="#方法-1-在-github-上在线修改" aria-label="Permalink to “方法 1：在 GitHub 上在线修改”">​</a></h3><div class="info custom-block"><p class="custom-block-title">评价</p><p>难度：⭐</p><p>适用于修改简单的别字、语句不通或不清晰的描述等。</p></div><ol><li><p>在线修改</p><p>打开需要修改的文档网页，点击末尾左下角的「在 GitHub 上编辑此页」，网页会自动跳转到 GitHub 编辑文档源码的页面。</p><p><img src="/assets/%E8%B4%A1%E7%8C%AE%E6%8C%87%E5%8D%97-%E7%82%B9%E5%87%BB%E7%BC%96%E8%BE%91%E6%AD%A4%E9%A1%B5.CG6ypuas.png" alt="点击编辑此页" width="1530" height="774"></p><p>如果你是第一次贡献，则会提示需要 fork 才能继续，请点击「Fork this repositiry」继续即可。</p><p><img src="/assets/%E8%B4%A1%E7%8C%AE%E6%8C%87%E5%8D%97-fork%E4%BB%93%E5%BA%93.P6F4R8K0.png" alt="fork 仓库" width="1610" height="428"></p><p>编辑需要修改的地方，文档风格和 Markdown 语法请参阅 <a href="./markdown#文档语法风格">文档风格指南 #Markdown 语法</a>。</p></li><li><p>提交修改</p><p>修改完后，点击右上角的 <code>Commit Changes...</code>，</p><p><img src="/assets/%E8%B4%A1%E7%8C%AE%E6%8C%87%E5%8D%97-%E4%BF%AE%E6%94%B9%E5%86%85%E5%AE%B9.Dt5M4DnM.png" alt="修改内容" width="2846" height="1243"></p><p>在弹窗中在下方的「Commit changes」中输入有关此次修改的标题和具体描述。然后点击「Propose changes」。</p><p><img src="/assets/%E8%B4%A1%E7%8C%AE%E6%8C%87%E5%8D%97-%E8%BE%93%E5%85%A5%E6%8F%90%E4%BA%A4%E4%BF%A1%E6%81%AF.CFSQoVmP.png" alt="输入提交信息" width="1068" height="922"></p></li><li><p>提交 PR</p><p>在「Comparing changes」页面中，，点击「Create Pull request」。</p><p><img src="/assets/%E8%B4%A1%E7%8C%AE%E6%8C%87%E5%8D%97-%E5%88%9B%E5%BB%BApr2.BWVe1JVL.png" alt="创建 PR" width="2505" height="831"></p><p>输入此 PR 的标题和具体描述。点击「Create pull request」即可。</p><p><img src="/assets/%E8%B4%A1%E7%8C%AE%E6%8C%87%E5%8D%97-%E5%88%9B%E5%BB%BApr3.Ckw1SWu1.png" alt="创建 pr 详情" width="1865" height="1399"></p><p>PR 提交后，CI 工具会自动对提交的 PR 生成一个预览链接并评论在 PR 中，可以在此预览修改的结果。</p><p>维护者将尽快审核这些修改。</p></li></ol>`,16),a(`h3`,u,[c[0]||=s(`方法 2：通过代码空间在线修改`,-1),i(m,{text:`推荐`}),c[1]||=s(),c[2]||=a(`a`,{class:`header-anchor`,href:`#方法-2-通过代码空间在线修改`,"aria-label":`Permalink to “方法 2：通过代码空间在线修改”`},`​`,-1)]),c[4]||=o(`<div class="info custom-block"><p class="custom-block-title">评价</p><p>难度：⭐⭐</p><p>适用于一般修改。</p></div><p>例如你需要添加一篇文章，上传一些图片等，且对 Git 不甚了解，那么可以使用这种方式在线修改，这可以避免你下载很多软件。</p><p>请参考 <a href="./github-codespace">使用 <code>GitHub 代码空间</code> 修改文档</a>。</p><h3 id="方法-3-离线修改" tabindex="-1">方法 3：离线修改 <a class="header-anchor" href="#方法-3-离线修改" aria-label="Permalink to “方法 3：离线修改”">​</a></h3><div class="info custom-block"><p class="custom-block-title">评价</p><p>难度：⭐⭐⭐</p><p>适用于维护者。</p></div><p>如果你需要做较大量修改，例如增加几篇文章，或长期贡献/维护仓库，且对 Git 有一些了解，可以采用这种方式：完全本地修改，可以在本地预览修改的效果，修改后再推送到 GitHub。</p><p>请参考 <a href="./build">完全构建指南</a>。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>Commit 的注释信息应该是描述性的</li><li>希望读者对审稿人/维护者的评论和意见保持开放的心态，并努力改进代码或文档</li><li>新的 PR 不一定会及时审核，取决于审稿人/维护者的当时的工作时间</li></ul>`,9),i(h),i(g)])}var f=n(l,[[`render`,d]]);export{c as __pageData,f as default};